-- Seed the literary works in Supabase. Safe to rerun: existing records are left unchanged.
insert into public.literary_works (id, title, author, genre, period, tags, level, mark, cover, description, reading, intro, questions)
values
  ('qua-deo-ngang', 'Qua Đèo Ngang', 'Bà Huyện Thanh Quan', 'Thơ trung đại', 'Thơ • Lớp 7', ARRAY['Thiên nhiên', 'Cảm xúc', 'Thơ', 'Tình quê']::text[], 'Cơ bản', '詩', 'cover-green', 'Cảnh đèo lúc chiều tà gợi nỗi cô đơn, nhớ nước thương nhà và tâm trạng của người lữ khách.', 'Bước tới Đèo Ngang, bóng xế tà,
Cỏ cây chen đá, lá chen hoa.
Lom khom dưới núi, tiều vài chú,
Lác đác bên sông, chợ mấy nhà.
Nhớ nước đau lòng con quốc quốc,
Thương nhà mỏi miệng cái gia gia.
Dừng chân đứng lại, trời, non, nước,
Một mảnh tình riêng, ta với ta.', 'Bài thơ khắc họa cảnh Đèo Ngang trong thời khắc chiều tà. Không gian rộng, vắng và những dấu hiệu sự sống thưa thớt làm nổi bật tâm trạng cô đơn, hoài cổ của nhân vật trữ tình.', '[{"q":"Thời điểm được gợi ra ngay ở câu thơ đầu là gì?","opts":["Bình minh","Bóng xế tà","Đêm khuya","Buổi trưa"],"a":1,"why":"“Bóng xế tà” cho biết thời điểm chiều muộn, góp phần tạo sắc thái man mác buồn."},{"q":"Cụm từ “lom khom”, “lác đác” có tác dụng nổi bật nào?","opts":["Làm cảnh vật trở nên đông vui","Nhấn mạnh sự hùng vĩ dữ dội","Gợi dáng vẻ nhỏ bé, thưa vắng của sự sống","Miêu tả một phiên chợ náo nhiệt"],"a":2,"why":"Hai từ láy gợi hình làm nổi bật sự nhỏ bé và thưa thớt giữa không gian rộng lớn."},{"q":"“Một mảnh tình riêng, ta với ta” thể hiện điều gì?","opts":["Niềm vui hội ngộ","Tâm sự riêng tư, cô đơn của nhân vật trữ tình","Sự tức giận với người đi đường","Lời mời bạn bè đến chơi"],"a":1,"why":"Câu kết thu lại không gian vào thế giới nội tâm, nhấn mạnh nỗi cô đơn và tâm sự riêng."}]'::jsonb),
  ('ban-den-choi-nha', 'Bạn đến chơi nhà', 'Nguyễn Khuyến', 'Thơ trào phúng / trữ tình', 'Thơ • Lớp 7', ARRAY['Tình bạn', 'Hài hước', 'Thơ', 'Đời sống']::text[], 'Cơ bản', '友', 'cover-gold', 'Tiếng cười hóm hỉnh làm nổi bật tình bạn chân thành, vượt lên trên vật chất và lễ nghi.', 'Đã bấy lâu nay, bác tới nhà,
Trẻ thời đi vắng, chợ thời xa.
Ao sâu nước cả, khôn chài cá,
Vườn rộng rào thưa, khó đuổi gà.
Cải chửa ra cây, cà mới nụ,
Bầu vừa rụng rốn, mướp đương hoa.
Đầu trò tiếp khách, trầu không có,
Bác đến chơi đây, ta với ta.', 'Bài thơ dựng lên tình huống tiếp bạn rất đặc biệt: mọi thứ tưởng như sẵn có lại đều thiếu hoặc chưa dùng được. Cách nói hóm hỉnh dẫn đến lời khẳng định tình bạn chân thành, không phụ thuộc mâm cao cỗ đầy.', '[{"q":"Tình huống tiếp bạn trong bài thơ có điểm gì đặc biệt?","opts":["Gia chủ chuẩn bị rất chu đáo","Mọi thứ đều thiếu hoặc chưa thể dùng để đãi bạn","Hai người gặp nhau ngoài chợ","Bạn đến để vay tiền"],"a":1,"why":"Các chi tiết về trẻ, chợ, cá, gà, rau quả và trầu đều tạo nên tình huống thiếu thốn đầy hóm hỉnh."},{"q":"Giọng điệu chủ đạo của bài thơ là gì?","opts":["Hóm hỉnh, thân tình","Bi thương, tuyệt vọng","Oai nghiêm, trang trọng","Gay gắt, thù địch"],"a":0,"why":"Cách liệt kê những cái “không có” tạo tiếng cười nhẹ nhàng, thân mật."},{"q":"Thông điệp chính của bài thơ là gì?","opts":["Muốn có bạn phải giàu có","Lễ nghi quan trọng hơn tình cảm","Tình bạn chân thành không đặt nặng vật chất","Không nên đón khách ở nhà"],"a":2,"why":"Điều quý giá nhất khi bạn đến chơi là tình cảm chân thành, không phải đồ ăn thức uống."}]'::jsonb),
  ('lao-hac', 'Lão Hạc', 'Nam Cao', 'Truyện ngắn hiện thực', 'Truyện • Lớp 8', ARRAY['Gia đình', 'Xã hội', 'Cảm xúc', 'Đời sống']::text[], 'Trung bình', '家', 'cover-rose', 'Số phận người nông dân nghèo và vẻ đẹp của lòng tự trọng, tình yêu thương trong hoàn cảnh khốn cùng.', 'Lão Hạc là một người nông dân nghèo, sống cùng con chó mà lão yêu quý như một người thân. Con trai vì không đủ tiền cưới vợ nên bỏ đi làm đồn điền cao su. Lão ở lại một mình, làm thuê và chắt chiu từng chút để giữ mảnh vườn cho con.

Khi bệnh tật, mất mùa khiến cuộc sống ngày càng khó khăn, lão buộc phải bán con chó. Quyết định ấy khiến lão đau đớn, day dứt. Lão gửi ông giáo tiền lo ma chay và nhờ giữ hộ mảnh vườn, quyết không tiêu vào phần của con.

Qua câu chuyện, người đọc thấy được cảnh nghèo đói bủa vây người nông dân trước Cách mạng, đồng thời cảm nhận tình yêu con sâu nặng, lòng tự trọng và nhân cách đáng quý của lão Hạc.', 'Đây là phần đọc học tập tóm lược nội dung và chủ đề của truyện, không thay thế văn bản đầy đủ. Hãy chú ý mối quan hệ giữa hoàn cảnh nghèo đói, tình yêu con và lựa chọn giữ gìn lòng tự trọng của nhân vật.', '[{"q":"Lão Hạc cố giữ lại mảnh vườn chủ yếu vì điều gì?","opts":["Muốn bán được giá cao","Muốn để lại cho con trai","Muốn xây nhà mới","Không thích người khác làm vườn"],"a":1,"why":"Mảnh vườn là phần lão muốn giữ lại cho con trai sau này."},{"q":"Việc bán cậu Vàng khiến lão Hạc cảm thấy thế nào?","opts":["Vui mừng vì có thêm tiền","Thờ ơ, không quan tâm","Đau đớn, day dứt","Tức giận với ông giáo"],"a":2,"why":"Con chó là người bạn thân thiết nên việc bán nó khiến lão đau khổ, ân hận."},{"q":"Phẩm chất nổi bật của lão Hạc qua câu chuyện là gì?","opts":["Ích kỷ và tham lam","Lòng tự trọng và tình yêu thương con","Ham danh vọng","Thích hưởng thụ"],"a":1,"why":"Dù nghèo khổ, lão vẫn nghĩ cho con và cố giữ gìn lòng tự trọng."}]'::jsonb),
  ('chi-pheo', 'Chí Phèo', 'Nam Cao', 'Truyện ngắn hiện thực', 'Truyện • Lớp 11', ARRAY['Xã hội', 'Cảm xúc', 'Tâm lý', 'Đời sống']::text[], 'Nâng cao', '人', 'cover-blue', 'Bi kịch bị cự tuyệt quyền làm người và khát vọng được trở lại với cộng đồng.', 'Chí Phèo vốn là một người nông dân hiền lành nhưng bị đẩy vào tù bởi những thế lực ở làng Vũ Đại. Khi trở về, Chí biến dạng cả về ngoại hình lẫn tính cách, thường xuyên say rượu và gây sự. Bá Kiến lợi dụng Chí như một công cụ để giải quyết mâu thuẫn.

Cuộc gặp gỡ với Thị Nở và bát cháo hành đem đến cho Chí một khoảnh khắc thức tỉnh. Lần đầu sau nhiều năm, Chí cảm nhận được sự chăm sóc giản dị và khao khát sống lương thiện. Nhưng định kiến của xã hội đã chặn mất con đường trở về.

Tác phẩm đặt ra câu hỏi đau đớn về quyền làm người: một con người có thể bị xã hội đẩy ra ngoài lề đến mức nào, và cộng đồng phải chịu trách nhiệm gì trước bi kịch ấy?', 'Phần đọc này tóm lược các nút thắt chính và chủ đề nhân đạo của truyện. Khi học, hãy chú ý sự thay đổi tâm lý của Chí trước và sau cuộc gặp Thị Nở.', '[{"q":"Bát cháo hành có ý nghĩa gì đối với Chí Phèo?","opts":["Chỉ giúp Chí no bụng","Khơi dậy cảm giác được yêu thương và khát vọng lương thiện","Khiến Chí muốn rời làng","Là món quà của Bá Kiến"],"a":1,"why":"Bát cháo hành là sự chăm sóc chân thành, giúp Chí thức tỉnh và khao khát trở lại làm người lương thiện."},{"q":"Bi kịch trung tâm của Chí Phèo là gì?","opts":["Không có tài sản thừa kế","Bị cự tuyệt quyền làm người và con đường trở về cộng đồng","Không muốn làm việc","Mất khả năng đọc viết"],"a":1,"why":"Tác phẩm phản ánh quá trình bị tha hóa và sự cự tuyệt của xã hội khi Chí muốn hoàn lương."},{"q":"Tác phẩm thể hiện rõ giá trị nhân đạo nào?","opts":["Ca ngợi bạo lực","Phủ nhận khả năng thay đổi của con người","Xót thương con người và phản ánh xã hội đã đẩy họ vào bi kịch","Khuyên người nghèo tránh giao tiếp"],"a":2,"why":"Tác phẩm lên án xã hội tàn nhẫn và thể hiện niềm cảm thương với khát vọng làm người."}]'::jsonb),
  ('truyen-kieu', 'Truyện Kiều', 'Nguyễn Du', 'Truyện thơ Nôm', 'Truyện thơ • Lớp 9', ARRAY['Tình yêu', 'Gia đình', 'Cảm xúc', 'Thơ']::text[], 'Trung bình', '夢', 'cover-violet', 'Tác phẩm lớn về số phận con người, tình yêu, chữ hiếu và khát vọng công lý.', 'Truyện Kiều kể về cuộc đời Thúy Kiều, một người con gái tài sắc. Vì biến cố gia đình, Kiều quyết định bán mình để cứu cha và em, từ đó trải qua nhiều năm lưu lạc, chịu nhiều bất công và đau khổ.

Trên hành trình ấy, Kiều gặp những con người với tính cách và số phận khác nhau. Tác phẩm vừa khắc họa tài năng, phẩm giá và đời sống nội tâm phong phú của nhân vật, vừa phơi bày những thế lực đồng tiền và bất công đã chà đạp con người.

Qua số phận Thúy Kiều, Nguyễn Du thể hiện niềm thương cảm sâu sắc đối với con người, đặc biệt là người phụ nữ, đồng thời đặt ra những suy ngẫm về tình yêu, chữ hiếu và công lý.', 'Phần đọc học tập tóm lược cốt truyện và chủ đề. Hãy nhìn nhận các lựa chọn của Thúy Kiều trong bối cảnh những ràng buộc gia đình và xã hội thời phong kiến.', '[{"q":"Quyết định bán mình của Thúy Kiều xuất phát chủ yếu từ điều gì?","opts":["Mong muốn rời xa gia đình","Muốn cứu cha và em, thể hiện chữ hiếu","Muốn trở nên nổi tiếng","Muốn đi du lịch"],"a":1,"why":"Kiều hy sinh tình riêng và bản thân để cứu gia đình, thể hiện sâu sắc chữ hiếu."},{"q":"Một giá trị nhân đạo nổi bật của Truyện Kiều là gì?","opts":["Đề cao sự giàu có bằng mọi giá","Cảm thương số phận con người và người phụ nữ","Ủng hộ mọi bất công xã hội","Chỉ kể chuyện phiêu lưu"],"a":1,"why":"Nguyễn Du thể hiện sự cảm thông sâu sắc với những đau khổ và phẩm giá của con người."},{"q":"Tác phẩm được viết chủ yếu bằng thể loại nào?","opts":["Truyện thơ Nôm","Kịch nói","Tùy bút hiện đại","Sử thi bằng văn xuôi"],"a":0,"why":"Truyện Kiều là truyện thơ Nôm, viết bằng thể thơ lục bát."}]'::jsonb),
  ('dong-chi', 'Đồng chí', 'Chính Hữu', 'Thơ hiện đại', 'Thơ • Lớp 9', ARRAY['Tình bạn', 'Chiến tranh', 'Cảm xúc', 'Thơ']::text[], 'Cơ bản', '兵', 'cover-teal', 'Tình đồng đội hình thành từ chung cảnh ngộ, lý tưởng và những năm tháng chiến đấu gian khổ.', 'Bài thơ khắc họa những người lính xuất thân từ các miền quê nghèo, cùng chung nhiệm vụ và trải qua thiếu thốn nơi chiến trường. Từ những điểm tương đồng trong hoàn cảnh, họ thấu hiểu, sẻ chia và gắn bó với nhau.

Tình đồng chí hiện lên qua những chi tiết đời thường: cùng chịu rét, cùng chia sẻ khó khăn, cùng đứng bên nhau giữa đêm phục kích. Hình ảnh kết thúc giàu chất biểu tượng làm sáng lên vẻ đẹp bình dị mà kiên cường của người lính.', 'Hãy đọc chú ý sự chuyển biến từ những điểm chung trong hoàn cảnh xuất thân đến sự gắn bó sâu sắc giữa những người lính.', '[{"q":"Cơ sở hình thành tình đồng chí trong bài thơ là gì?","opts":["Lợi ích vật chất","Chung cảnh ngộ, lý tưởng và nhiệm vụ","Quan hệ họ hàng","Cạnh tranh thành tích"],"a":1,"why":"Sự tương đồng về xuất thân, nhiệm vụ và lý tưởng tạo nền tảng cho tình đồng chí."},{"q":"Tình đồng chí được thể hiện rõ nhất qua điều gì?","opts":["Sự xa cách","Chia sẻ thiếu thốn và cùng chiến đấu","Những lời khoe khoang","Sự giàu sang"],"a":1,"why":"Những chi tiết sinh hoạt và chiến đấu cho thấy sự gắn bó, sẻ chia của người lính."},{"q":"Giọng điệu chung của bài thơ là gì?","opts":["Chân thành, mộc mạc mà sâu sắc","Châm biếm gay gắt","Hài hước suốt bài","Lạnh lùng, khách quan"],"a":0,"why":"Ngôn ngữ mộc mạc tạo nên cảm xúc chân thành, sâu sắc."}]'::jsonb)
on conflict (id) do nothing;

